#include "paleo_stratigraphy/core.h"
#include <cmath>
#include <iostream>
#include <numbers>
#include <stdexcept>
#include <algorithm>

using namespace paleo::stratigraphy;
namespace {
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void near(double a,double b,double eps,const char* message){check(std::isfinite(a)&&std::isfinite(b)&&std::abs(a-b)<=eps,message);}
template<class F>void rejects(F action,const char* message){bool threw=false;try{action();}catch(const std::exception&){threw=true;}check(threw,message);}
InterpretationBoundary marker(std::string id,std::string name,double md){InterpretationBoundary b;b.id=id;b.name=name;b.role=name;b.md=md;b.originalMd=md;b.source="manual";b.status="confirmed";b.locked=true;return b;}
InterpretationCycle cycle(std::string id,std::string top,std::string bottom,int sign){InterpretationCycle c;c.id=id;c.name=id;c.segmentId="E12";c.topBoundaryId=top;c.bottomBoundaryId=bottom;c.direction=sign;c.source="manual";c.status="confirmed";return c;}
WellInterpretation reference(){WellInterpretation w;w.wellId=1;w.name="SYNTH-REF";w.boundaries={marker("r0","T70",100),marker("r1","c1",160),marker("r2","c2",230),marker("r3","T72",300)};w.cycles={cycle("c0","r0","r1",1),cycle("c1","r1","r2",-1),cycle("c2","r2","r3",1)};auto p=cycle("parent","r0","r3",-1);p.level=3;for(auto& c:w.cycles)c.parentId=p.id;w.cycles.push_back(p);return w;}
WellInterpretation target(){WellInterpretation w;w.wellId=2;w.name="SYNTH-TARGET";w.boundaries={marker("t0","T70",100),marker("t3","T72",300)};w.input.wellId=2;auto& s=w.input.log;s.id="GR";s.name="GR";s.kind="GR";s.unit="API";for(int i=0;i<=400;++i){s.axis.push_back(i);s.values.push_back(60+15*std::tanh((i-159.)/3)-20*std::tanh((i-232.)/4)+2*std::sin(i*.5));}return w;}
void signalTests(){
    auto f=burgPace({-1,0,1,0},1,"forward");std::vector<double> expected{0,0,1,1};for(size_t i=0;i<f.size();++i)near(f[i],expected[i],1e-12,"Burg AR1 reference output differs");auto r=burgPace({-1,0,1,0},1,"reverse");expected={0,1,1,0};for(size_t i=0;i<r.size();++i)near(r[i],expected[i],1e-12,"Reverse AR1 output differs");rejects([]{burgPace({1,Missing,2},2);},"Burg must reject gaps passed as a continuous segment");
    // Independent golden outputs from the retained legacy NumPy Burg routine;
    // this executable has no Python dependency and the fixture is synthetic.
    std::vector<double> fixture{12,19,11,8,17,24,15,9,18,21,14,7};
    std::vector<double> goldenForward{0,0,0,.19088957034087706,.4219007518703841,4.927762072643761,6.30331474699856,7.293929759954533,8.895877275323771,8.7330617842333,10.869139163374843,7.271408070307632};
    std::vector<double> goldenReverse{.6507277039901354,5.007787316873968,5.726614653693317,8.950231732919114,8.884720500765566,7.72105134141452,4.996211161301355,2.309511097345259,3.7574497520173193,0,0,0};
    auto legacyF=burgPace(fixture,3,"forward"),legacyR=burgPace(fixture,3,"reverse"),legacyB=burgPace(fixture,3,"bidirectional");
    for(size_t i=0;i<fixture.size();++i){near(legacyF[i],goldenForward[i],1e-9,"Burg AR3 must match legacy numerical convention");near(legacyR[i],goldenReverse[i],1e-9,"Reverse Burg AR3 must match legacy numerical convention");near(legacyB[i],.5*(goldenForward[i]+goldenReverse[i]),1e-9,"Bidirectional PACE reference failed");}
    for(int n:{32,37,101}){std::vector<double> x;for(int i=0;i<n;++i)x.push_back(std::cos(2*std::numbers::pi*3*i/n));auto pos=cosinePhase(x,false),neg=cosinePhase(x,true);for(int i=0;i<n;++i){near(pos[i],x[i],2e-10,"Hilbert +cos reference failed");near(neg[i],-x[i],2e-10,"Hilbert sign convention failed");}}
    auto w=target();w.input.log.values[200]=Missing;CorrelationAlgorithmProfile p;p.arOrders={5,9};p.padding=20;p.sampleStep=.5;auto d=deriveCurves(w.input.log,p,50,350);check(d.series.size()==6,"Expected two PACE, residual, two phases and median");auto& pace=d.series[0];check(pace.axis.size()==601&&pace.axis.size()==pace.values.size(),"Derived axis must retain display grid and gaps");auto i=std::lower_bound(pace.axis.begin(),pace.axis.end(),200)-pace.axis.begin();check(!std::isfinite(pace.values[i])&&(pace.quality[i]&1),"Missing GR sample must not be synthesized");check(std::any_of(pace.quality.begin(),pace.quality.end(),[](auto q){return (q&2)!=0;}),"Interpolation quality is required");check(std::any_of(pace.quality.begin(),pace.quality.end(),[](auto q){return (q&4)!=0;}),"Per-gap AR initialization must be masked");
    p.resample=false;auto native=deriveCurves(w.input.log,p,50,350);check(native.series[0].axis.size()==301,"Native sample mode may not generate sample grid");p.normalize=true;auto norm=deriveCurves(w.input.log,p,50,350);for(const auto& s:norm.series)if(s.kind=="PACE"||s.kind=="FISCHER_GR_RESIDUAL")for(double v:s.values)if(std::isfinite(v))check(v>=-1e-10&&v<=1+1e-10,"Normalized cumulative curves must remain [0,1]");
    w.input.log.axisKind="TWT";rejects([&]{deriveCurves(w.input.log,p,50,350);},"Time axis must not be treated as MD");
}
void interpretationTests(){
    auto ref=reference();check(validateInterpretation(ref).empty(),"Synthetic reference should validate");auto t=extractTemplate(ref,"SYNTH-TEMPLATE","1");check(t.segments.size()==1&&t.segments[0].parentGroups.size()==3,"Template must retain explicit parent groups");near(t.segments[0].boundaryFractions[1],.3,1e-12,"Template must retain actual manual interval ratio");check(t.segments[0].parentDirections[0]==-1,"Template must preserve standard L3 polarity");
    auto w=target();w.boundaries.push_back(marker("pin","manual pick",160));CorrelationAlgorithmProfile p;p.arOrders={5,9};p.padding=20;p.minimumThickness=12;auto out=divideSegment(w,t,"E12",p);check(out.cycles.size()==4,"Three L4 and one shared-boundary L3 required");check(std::any_of(out.boundaries.begin(),out.boundaries.end(),[](auto b){return b.id=="pin"&&b.md==160;}),"Manual protected boundary must survive exact");w.boundaries=out.boundaries;w.cycles=out.cycles;check(validateInterpretation(w).empty(),"Generated hierarchy must validate");auto parent=std::find_if(w.cycles.begin(),w.cycles.end(),[](auto c){return c.level==3;});check(parent!=w.cycles.end()&&parent->direction==-1,"L3 must inherit explicit standard polarity");
    auto before=w;rejects([&]{moveBoundary(w,"pin",350);},"Crossing interval move must be rejected");near(std::find_if(w.boundaries.begin(),w.boundaries.end(),[](auto b){return b.id=="pin";})->md,160,1e-12,"Rejected move must leave document untouched");moveBoundary(w,"pin",162);auto moved=std::find_if(w.boundaries.begin(),w.boundaries.end(),[](auto b){return b.id=="pin";});near(moved->originalMd,160,1e-12,"Manual drag must preserve original MD");check(moved->locked&&moved->source=="manual","Manual drag must lock interpretation");
    auto rerun=divideSegment(w,t,"E12",p);check(std::any_of(rerun.boundaries.begin(),rerun.boundaries.end(),[](auto b){return b.id=="pin"&&b.md==162&&b.originalMd==160;}),"Algorithm rerun must keep the dragged shared boundary and original source depth");
    check(!out.usedSeries.empty()&&!out.usedSeries.front().runId.empty()&&out.usedSeries.front().segmentId=="E12","DP must return the exact derived curves it used with run/segment identity");
    auto cdmt=fischerCdmt(ref,"E12",4);check(cdmt.axisKind=="CYCLE_INDEX"&&cdmt.unit=="m","CDMT axis and units must differ from log-derived Fischer");near(cdmt.values[1],60-200./3,1e-10,"CDMT must use actual cycle thickness");near(cdmt.values.back(),0,1e-10,"CDMT cumulative deviation must end at zero");auto flat=target();std::fill(flat.input.log.values.begin(),flat.input.log.values.end(),50.);rejects([&]{divideSegment(flat,t,"E12",p);},"No signal must not fall back to uniform segmentation");auto self=target();self.wellId=1;rejects([&]{divideSegment(self,t,"E12",p);},"Target cannot be its own reference");
    w.series=out.usedSeries;w.series.push_back(fischerCdmt(w,"E12",4));auto other=w.series.front();other.id="other-region";other.segmentId="E4";w.series.push_back(other);auto savedValues=w.series[0].values;auto savedParameters=w.series[0].parametersJson;moveBoundary(w,"t0",99);check(w.series.size()==out.usedSeries.size()+2&&w.series[0].status=="stale","Regional edits must retain derived arrays and mark them stale");check(w.series[0].values==savedValues&&w.series[0].parametersJson==savedParameters,"Invalidation must preserve computed values and parameters");check(w.series.back().status=="current","Unrelated regional series must remain current");
}
GeologicalInterval interval(std::string name,double top,double bottom,int row){GeologicalInterval i;i.intervalName=name;i.topDepth=top;i.bottomDepth=bottom;i.sourceRow=row;i.intervalId=row;return i;}
void manualAndClusterTests(){
    auto input=target().input;input.wellId=19;input.well.wellName="SYNTH-MANUAL";input.formationTrackId=1;input.intervalTrackId=2;input.manualLevel3TrackId=3;
    for(auto* track:{&input.formationTrack,&input.manualTrack,&input.manualLevel3Track}){track->depthInfo.depthType="MD";track->depthInfo.depthUnit="m";track->depthInfo.mdReference="RKB";}
    input.formationTrack.trackName="段";input.formationTrack.intervals={interval("恩平一-二段",100,300,1)};
    input.manualTrack.trackName="四级";input.manualTrack.intervals={interval("正旋回",100.5,160,1),interval("反旋回",160,230,2),interval("正旋回",230,299.5,3)};
    input.manualLevel3Track.trackName="三级";input.manualLevel3Track.intervals={interval("反旋回",101,299,1)};
    auto manual=makeManualInterpretation(input);check(manual.cycles.size()==4,"Separate XML track names must provide explicit L3/L4 levels");check(std::all_of(manual.cycles.begin(),manual.cycles.end(),[](const auto& c){return c.source=="imported_interpretation";}),"Manual source classification must be retained");
    check(validateInterpretation(manual).empty(),"Unreconciled manual layers must remain valid independent interpretations");
    rejects([&]{extractTemplate(manual,"RAW","1");},"Strict template extraction must reject uncovered frame margins");
    auto reconciled=extractTemplate(manual,"MAPPED","1",2.0);check(reconciled.segments[0].parentGroups.size()==3&&reconciled.segments[0].parentDirections[0]==-1,"Explicit tolerance must map source L3 to L4 ordinals");
    check(reconciled.sourceReconciliationJson.find("sourceDepthsModified\":false")!=std::string::npos,"Source mapping receipt must declare no source movement");
    check(std::any_of(manual.boundaries.begin(),manual.boundaries.end(),[](auto b){return b.md==100.5;})&&std::any_of(manual.boundaries.begin(),manual.boundaries.end(),[](auto b){return b.md==101;}),"Original distinct L3/L4 endpoint depths must remain unchanged");
    auto unknown=input;unknown.manualTrack.depthInfo.depthUnit.clear();rejects([&]{makeManualInterpretation(unknown);},"Unknown manual depth units require confirmation");GeometryOptions options;options.confirmedDepthUnit="m";auto confirmed=makeManualInterpretation(unknown,options);check(confirmed.cycles.size()==4&&unknown.manualTrack.depthInfo.depthUnit.empty(),"Manual confirmation must use a calculation copy");
    std::vector<WellInterpretation> wells;for(int n=0;n<4;++n){auto w=target();w.wellId=n+1;w.input.wellId=w.wellId;w.boundaries={marker("a","T70",100),marker("b","T80",300)};for(size_t j=0;j<w.input.log.values.size();++j){double u=(w.input.log.axis[j]-100)/200;w.input.log.values[j]=60+20*(n<2?std::sin(u*4*std::numbers::pi):std::cos(u*2*std::numbers::pi))+.02*n*std::sin(u*17);}wells.push_back(w);}
    auto clustering=clusterWells(wells,2);check(clustering.members.size()==4,"Clustering must include eligible wells");check(clustering.members[0].group==clustering.members[1].group&&clustering.members[2].group==clustering.members[3].group&&clustering.members[0].group!=clustering.members[2].group,"Observed GR shapes must drive cluster assignments");std::reverse(wells.begin(),wells.end());auto again=clusterWells(wells,2);check(again.inputFingerprint==clustering.inputFingerprint&&again.members[0].group==clustering.members[0].group,"Clustering must be deterministic regardless of input order");rejects([&]{clusterWells(wells,5);},"More clusters than wells must be rejected");
}
CorrelationWellInput geometricWell(){CorrelationWellInput w;w.wellId=7;w.log.axis={0,1000};w.log.values={50,60};w.depthInfo.depthType="MD";w.depthInfo.depthUnit="m";w.depthInfo.mdReference="RKB";w.well.wellheadX=-500;w.well.wellheadY=-500;w.well.coordinateSystem="SYNTH:LOCAL";w.well.coordinateUnit="m";auto& t=w.timeDepth;t.depthInfo=w.depthInfo;t.coordinateSystem="SYNTH:LOCAL";t.coordinateUnit="m";t.timeUnit="ms";t.timeType="TWT";t.timeReference="SYNTH:DATUM";t.depthTimePairs={{0,0,50,50,Missing},{1000,-2000,150,50,Missing}};return w;}
CorrelationHorizon horizon(){CorrelationHorizon h;h.resourceId=9;h.role="T70";h.surface.coordinateSystem="SYNTH:LOCAL";h.surface.coordinateUnit="m";h.surface.timeUnit="ms";h.surface.timeType="TWT";h.surface.timeReference="SYNTH:DATUM";h.surface.points={{10,20,0,0,1000},{11,20,200,0,1000},{10,21,0,100,1000},{11,21,200,100,1000}};return h;}
void geometryTests(){auto w=geometricWell();auto h=horizon();GeometryOptions o;o.wellTimeSign=-1;auto r=intersectHorizons(w,{h},o);check(r.boundaries.size()==1,"XYZ checkshot trajectory must intersect the horizon despite outside wellhead");near(r.boundaries[0].md,500,.02,"Surface intersection MD differs");near(r.boundaries[0].originalMd,500,.02,"Original horizon MD must be retained");check(r.boundaries[0].source=="seismic_horizon"&&!r.boundaries[0].evidenceJson.empty(),"Intersection provenance must be explicit");rejects([&]{intersectHorizons(w,{h});},"Negative TWT must require explicit sign convention");auto bad=h;bad.surface.coordinateSystem="SYNTH:OTHER";rejects([&]{intersectHorizons(w,{bad},o);},"CRS mismatch must not be guessed");bad=h;bad.surface.timeType="";rejects([&]{intersectHorizons(w,{bad},o);},"Missing time type must be rejected");bad=h;for(auto& p:bad.surface.points)p.x+=1000;auto miss=intersectHorizons(w,{bad},o);check(miss.boundaries.empty()&&!miss.warnings.empty(),"Surface exterior must never be extrapolated");
    auto crossing=w;crossing.timeDepth.depthTimePairs.front().x=0;crossing.timeDepth.depthTimePairs.back().x=200;
    auto folded=h;folded.surface.points.clear();std::vector<double> xs{0,100.1,100.15,100.2,200},ts{-1,1000,1003.5,1001,1999};
    for(size_t i=0;i<xs.size();++i)for(int j=0;j<2;++j)folded.surface.points.push_back({int(i),j,xs[i],j*100.,ts[i]});
    GeometryOptions coarse=o;coarse.searchStepMd=100;auto doubleCross=intersectHorizons(crossing,{folded},coarse);
    check(doubleCross.boundaries.size()==2,"Exact triangle crossing must find two roots inside a coarse search step");near(doubleCross.boundaries[0].md,500.5833333333,1e-6,"First narrow crossing failed");near(doubleCross.boundaries[1].md,500.9166666667,1e-6,"Second narrow crossing failed");
    auto hole=h;hole.surface.points.clear();for(int i:{0,1,3,4})for(int j=0;j<3;++j)hole.surface.points.push_back({i,j,50.*i,50.*j,1000.});auto holeResult=intersectHorizons(crossing,{hole},o);check(holeResult.boundaries.empty(),"Missing horizon grid column must not be interpolated across");
    auto coincident=h;for(auto& point:coincident.surface.points)point.zTime=10*point.x;auto onSurface=intersectHorizons(crossing,{coincident},o);check(onSurface.boundaries.empty()&&std::any_of(onSurface.warnings.begin(),onSurface.warnings.end(),[](const auto& text){return text.find("no unique")!=std::string::npos;}),"Coincident trajectory must not invent one of infinitely many intersections");
    auto vertical=w;vertical.positions={{0,50,50,0,Missing},{500,75,50,200,Missing},{1000,150,50,1000,Missing}};vertical.depthInfo.tvdReference="KB";vertical.timeDepth.depthInfo.depthType="TVD";vertical.timeDepth.depthInfo.tvdReference="KB";vertical.timeDepth.depthTimePairs={{0,0},{1000,2000}};auto composed=intersectHorizons(vertical,{h});near(composed.boundaries.at(0).md,687.5,1e-8,"TWT(TVD(MD)) must preserve trajectory breakpoints rather than linearly interpolate sparse MD ties");
    auto unknown=w;auto unknownH=h;unknown.log.axisUnit.clear();unknown.log.axisKind.clear();unknown.depthInfo.depthUnit.clear();unknown.timeDepth.depthInfo.depthUnit.clear();unknown.timeDepth.depthInfo.depthType.clear();unknown.timeDepth.timeUnit.clear();unknownH.surface.timeUnit.clear();GeometryOptions confirmed=o;confirmed.confirmedDepthUnit="m";confirmed.confirmedDepthType="MD";confirmed.confirmedLogDepthType="MD";confirmed.confirmedWellTimeUnit="ms";confirmed.confirmedHorizonTimeUnit="ms";auto explicitResult=intersectHorizons(unknown,{unknownH},confirmed);near(explicitResult.boundaries.at(0).md,500,.02,"Explicit missing-metadata confirmations must enable computation");check(unknown.log.axisUnit.empty()&&unknown.timeDepth.timeUnit.empty()&&unknownH.surface.timeUnit.empty(),"Geometry must not mutate captured source metadata");check(explicitResult.boundaries[0].evidenceJson.find("explicitConfirmations")!=std::string::npos,"Geometry must persist confirmation receipt");confirmed.confirmedWellTimeUnit="s";rejects([&]{intersectHorizons(w,{h},confirmed);},"Confirmation must not overwrite a declared unit");
    CorrelationWellInput survey;survey.well.coordinateUnit="m";survey.well.wellheadX=100;survey.well.wellheadY=200;survey.surveyDepthInfo.depthUnit="m";survey.survey.azimuthReference="grid_north";survey.survey.surveyPoints={{0,45,90},{1000,45,90}};auto path=buildTrajectory(survey);near(path.back().x,100+1000/std::sqrt(2.),1e-8,"Minimum-curvature easting failed");near(path.back().tvd,1000/std::sqrt(2.),1e-8,"Minimum-curvature TVD failed");survey.survey.azimuthReference="magnetic";rejects([&]{buildTrajectory(survey);},"Uncorrected magnetic azimuth must be rejected");}
}
int main(){try{signalTests();interpretationTests();manualAndClusterTests();geometryTests();std::cout<<"stratigraphy core: all numeric, hierarchy, manual-template, clustering, edit and geometry checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
